	err = s.HandleTurnEnd(context.Background(), state)
	require.NoError(t, err)

	// Verify the checkpoint was created on the metadata branch
	store := checkpoint.NewGitStore(repo)
	cpID := id.MustCheckpointID("cafe0000babe")
